Plugins.Require("pay_activity", "common.config.LimitedTimeGiftCombinedConfig")

---@type IPayActivity
local IPayActivity = Plugins.Require("pay_activity", "common.class.IPayActivity")
---@class LimitedTimeGiftCombined : IPayActivity
local LimitedTimeGiftCombined = class("LimitedTimeGiftCombined", IPayActivity)

---@type LimitedTimeGiftCombinedConfig
local LimitedTimeGiftCombinedConfig = T(Global, "LimitedTimeGiftCombinedConfig")

---@type ReportEvent
local ReportEvent = T(Global, "ReportEvent")

function LimitedTimeGiftCombined:hasBought(key)
    local record = self.info:getValue("GiftCombinedRecord")
    if record then
        return record[key]
    end
end

function LimitedTimeGiftCombined:initDataInfo()
    self:initInfoKey("GiftCombinedRecord", {})
    self:registerC2SFunc("tryBuyGiftBag")
end

function LimitedTimeGiftCombined:tryBuyGiftBag(id)
    if not id then
        return
    end
    local record = self.info:getValue("GiftCombinedRecord")
    if not record then
        return
    end

    local cfg = LimitedTimeGiftCombinedConfig:getCfgById(id)
    print("------------------------------->>>> LimitedTimeGiftCombined:tryBuyGiftBag ", id, cfg.giftKey, record[cfg.giftKey])
    --LogUtil.pv(cfg)
    if not cfg or record[cfg.giftKey] then
        return
    end
    --if not self:canReward(cfg.giftContent) then
    --    return
    --end
    if isClient then
        PayHelper.checkMoney(CurrencyId.GCube, cfg.finalPrice, function(success)
            if success then
                self:runServerFunc("tryBuyGiftBag", id)
            end
        end)
    else
        if self.buyCtrl[cfg.giftKey] then
            return
        end
        self.buyCtrl[cfg.giftKey]=true
        PayHelper.payMoneySync(self.player, id, CurrencyId.GCube, cfg.finalPrice, function()
            --print(">>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> LimitedTimeGiftCombined  payMoneySync ")
            self.buyCtrl[cfg.giftKey]=false
            record[cfg.giftKey] = true
            self.info:setValue("GiftCombinedRecord", TableUtil.copyTable(record))
            self:playerGetGift(id)
        end, function ()
            self.buyCtrl[cfg.giftKey]=false
        end, nil, "Activity:" .. self.activityId)
    end
end

function LimitedTimeGiftCombined:playerGetGift(id)
    local cfg = LimitedTimeGiftCombinedConfig:getCfgById(id)
    if cfg and cfg.giftContent and cfg.giftContent ~= "" and cfg.giftContent ~= "#" then
        self:doReward(cfg.giftContent)
        --print("--------------------------------  report playerGetGift :",id)
        ReportEvent.reportEvent(self.player.userId, "limited_giftpack_buy", false, {
            limited_gift_id = id,
        })
    end
    return true
end

function LimitedTimeGiftCombined:tryShowEntryUI()
    if not isClient then
        return
    end
    local giftBag = LimitedTimeGiftCombinedConfig:getCfgByActivityId(self.activityId)
    --print("--------------------LimitedTimeGiftCombined:tryShowEntryUI()",giftBag.giftKey,self:hasBought(giftBag.giftKey))
    if giftBag and not self:hasBought(giftBag.giftKey) then
        self.entryLayout = UIHelper.showGameGUILayout("GUILimitTimeCombinationEntry", self.activityId)
    end
end

function LimitedTimeGiftCombined:onStop()
    if isClient then
        UIHelper.hideGameGUILayout(self.cfg.activityUIName)
        UIHelper.hideGameGUILayout("GUILimitTimeCombinationEntry")
    end
end

function LimitedTimeGiftCombined:onStart()
    self.buyCtrl={}
    if isClient then
        self.info:addKeyObserver("GiftCombinedRecord", function(activity, key, value)
            --print("================>>addKeyObserver  ",key,value)
            --LogUtil.pv(value)
            Events.PayActivityGiftCombinedRecord:invoke()
        end)

        local giftBag = LimitedTimeGiftCombinedConfig:getCfgByActivityId(self.cfg.id)
        if giftBag and giftBag.giftContent and next(giftBag.giftContent) ~= nil then
            self:requestCheckPlayerHasRewardItem(giftBag.giftContent, function(ret)
                if ret then
                    local allHave=true
                    for _, v in pairs(giftBag.giftContent) do
                        if not ret[v] then
                            allHave=false
                            break
                        end
                    end
                    --print("------------------------ LimitedTimeGiftCombined:onStart(),buyCount  ",allHave,#giftBag.giftContent)
                    if allHave then
                        self:onStop()
                    end
                end
            end)
        end
    end
end

return LimitedTimeGiftCombined